class DisjointSets:
    def __init__(self, n):
        if type(n) is not int or n < 0:
            raise ValueError("invalid element count")
        self.parent = list(range(n))
        self.size = [1] * n
        self.components = n

    def find(self, vertex):
        if type(vertex) is not int or not 0 <= vertex < len(self.parent):
            raise ValueError("invalid element")
        root = vertex
        while self.parent[root] != root:
            root = self.parent[root]
        while self.parent[vertex] != vertex:
            following = self.parent[vertex]
            self.parent[vertex] = root
            vertex = following
        return root

    def union(self, a, b):
        # Validate both endpoints before find can compress either path.
        for vertex in (a, b):
            if type(vertex) is not int or not 0 <= vertex < len(self.parent):
                raise ValueError("invalid element")
        a, b = self.find(a), self.find(b)
        if a == b:
            return False
        if self.size[a] < self.size[b]:
            a, b = b, a
        self.parent[b] = a
        self.size[a] += self.size[b]
        self.components -= 1
        return True

    def component_size(self, vertex):
        return self.size[self.find(vertex)]

sets = DisjointSets(5)
print(sets.union(0, 1))
print(sets.union(1, 2))
print(sets.union(2, 0))
print(sets.find(0) == sets.find(2))
print(sets.component_size(1))
print(sets.components)

