class CoverageDSU:

    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, x):
        root = x
        while root != self.parent[root]:
            root = self.parent[root]
        while x != root:
            old_parent = self.parent[x]
            self.parent[x] = root
            x = old_parent
        return root

    def union(self, a, b):
        (a, b) = (self.find(a), self.find(b))
        if a == b:
            return False
        if self.size[a] < self.size[b]:
            (a, b) = (b, a)
        self.parent[b] = a
        self.size[a] += self.size[b]
        return True

def hundredths(text):
    negative = text.startswith('-')
    magnitude = text[1:] if negative else text
    (whole, fractional) = magnitude.split('.')
    units = 100 * int(whole) + int(fractional)
    return -units if negative else units

def clusters(n, theta, edges):
    threshold = hundredths(theta)
    dsu = CoverageDSU(n)
    for (a, b, rho) in edges:
        if hundredths(rho) > threshold:
            dsu.union(a, b)
    groups = {}
    for value in range(n):
        root = dsu.find(value)
        groups.setdefault(root, []).append(value)
    ordered = sorted(groups.values(), key=lambda members: members[0])
    return [str(len(ordered))] + [' '.join(map(str, group)) for group in ordered]

print(clusters(5, '0.50', [(0, 1, '0.80'), (1, 2, '0.55'), (3, 4, '0.50'), (0, 2, '-0.20')]))
print(clusters(2, '-0.20', [(0, 1, '-0.20'), (0, 1, '-0.19')]))

