def mst_weight(n, edges):
    dsu = CoverageDSU(n)
    total = selected = 0
    for (u, v, weight) in sorted(edges, key=lambda edge: edge[2]):
        if dsu.union(u, v):
            total += weight
            selected += 1
    return [str(total if selected == n - 1 else -1)]

print(mst_weight(4, [(0, 1, 1), (1, 2, 2), (0, 2, 2), (2, 3, 5), (1, 3, 4)]))
print(mst_weight(3, [(0, 1, 1)]))
print(mst_weight(1, [(0, 0, 7)]))
